import asyncio
import aiohttp
import json
import subprocess
import time
from collections import deque
from typing import Dict, Any, Optional

class URLCommandRunner:
    def __init__(self):
        self.url_queue = deque()
        self.fetch_tasks = set()
        self.max_concurrent = 4
        self.min_delay_ms = 200

    async def fetch_url(self, url: str) -> Optional[str]:
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url) as response:
                    return await response.text()
        except Exception as e:
            return None

    async def run_command(self, command: str, input_data: str) -> Dict[str, Any]:
        try:
            process = await asyncio.create_subprocess_shell(
                command,
                stdin=asyncio.subprocess.PIPE,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE
            )
            stdout, stderr = await process.communicate(input=input_data.encode())
            return {
                'exit_code': process.returncode,
                'stdout': stdout.decode().strip(),
                'stderr': stderr.decode().strip()
            }
        except Exception as e:
            return {'error': str(e)}

    async def process_url(self, url: str, command: str):
        start_time = time.time()
        while len(self.fetch_tasks) >= self.max_concurrent:
            await asyncio.sleep(0.001)
            if time.time() - start_time >= self.min_delay_ms / 1000:
                break

        fetch_task = asyncio.create_task(self.fetch_url(url))
        self.fetch_tasks.add(fetch_task)

        try:
            response = await asyncio.wait_for(fetch_task, timeout=10.0)
            if response is None:
                return

            command_result = await self.run_command(command, response)
            print(json.dumps({
                'url': url,
                **command_result
            }))
        except asyncio.TimeoutError:
            print(json.dumps({'url': url, 'error': 'Timeout fetching URL'}))
        finally:
            self.fetch_tasks.remove(fetch_task)

    async def main(self):
        while True:
            line = input().strip()
            if not line:
                break
            url, command = line.split(maxsplit=1)
            await self.process_url(url, command)

async def main():
    runner = URLCommandRunner()
    await runner.main()

if __name__ == '__main__':
    asyncio.run(main())
